describe('Interactive Toast Notifications - Screen Reader Announcement', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should announce toast notification content to screen readers on success', () => {
    // Intercept the API call for toast notification
    cy.intercept('POST', '/api/toast').as('showToast');

    // Trigger the toast notification
    cy.get('[data-testid="show-toast-button"]').click();

    // Wait for the API call and verify the toast appears
    cy.wait('@showToast');
    cy.get('[data-testid="toast-notification"]').should('be.visible');

    // Verify the toast contains the correct success message
    cy.get('[data-testid="toast-notification"]').should('contain', 'Success');
    cy.get('[data-testid="toast-notification"]').should('contain', 'Item added to cart');

    // Verify aria-live region is present and configured for screen reader announcement
    cy.get('[data-testid="toast-notification"]').should('have.attr', 'aria-live', 'polite');

    // Verify role is set for screen reader context
    cy.get('[data-testid="toast-notification"]').should('have.attr', 'role', 'alert');

    // Verify toast has a dismiss button
    cy.get('[data-testid="toast-dismiss-button"]').should('be.visible');

    // Verify toast is dismissible
    cy.get('[data-testid="toast-dismiss-button"]').click();
    cy.get('[data-testid="toast-notification"]').should('not.exist');
  });

  it('should announce error toast notification and handle dismiss action', () => {
    // Intercept the API call for error toast
    cy.intercept('POST', '/api/toast').as('showErrorToast');

    // Trigger the error toast
    cy.get('[data-testid="show-error-toast-button"]').click();

    // Wait for the API call and verify the error toast appears
    cy.wait('@showErrorToast');
    cy.get('[data-testid="toast-notification"]').should('be.visible');

    // Verify the toast contains the correct error message
    cy.get('[data-testid="toast-notification"]').should('contain', 'Error');
    cy.get('[data-testid="toast-notification"]').should('contain', 'Failed to connect to server');

    // Verify aria-live region is present for error announcement
    cy.get('[data-testid="toast-notification"]').should('have.attr', 'aria-live', 'assertive');

    // Verify toast has a close button
    cy.get('[data-testid="toast-dismiss-button"]').should('be.visible');

    // Verify toast can be dismissed by clicking the close button
    cy.get('[data-testid="toast-dismiss-button"]').click();
    cy.get('[data-testid="toast-notification"]').should('not.exist');

    // Verify toast can also be dismissed by pressing Escape key
    cy.get('[data-testid="toast-notification"]').should('be.visible');
    cy.get('body').type('{esc}');
    cy.get('[data-testid="toast-notification"]').should('not.exist');
  });
});
